const char *IanaLookup(const IanaPrefEntry *table,
                            size_t count,
                            const char *key)
{
    size_t lo = 0;
    size_t hi = count;
    if (!table || !key || count == 0) {
        return NULL;
    }
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        int cmp = strcmp(key, table[mid].from);
        if (cmp == 0) {
            return table[mid].to;
        }
        if (cmp < 0) {
            hi = mid;
        } else {
            lo = mid + 1u;
        }
    }
    return NULL;
}

